# Check DASEi websites without importing hooks DASEI_CODES = ['dasei0', 'dasei1', 'dasei2', 'dasei3'] DASEI_NAMES = { 'dasei0': 'Quick Entry', 'dasei1': 'Einstiege', 'dasei2': 'Grundstufe', 'dasei3': 'Aufbaustufe', }
Website = env['website'] existing = Website.search([('domain_code', 'in', DASEI_CODES)]) existing_codes = set(existing.mapped('domain_code')) missing_codes = [c for c in DASEI_CODES if c not in existing_codes]
if not missing_codes: message = "✅ All DASEi websites exist:

" for ws in existing.sorted(key=lambda w: w.domain_code): message += f"• {ws.domain_code}: {ws.name}
" else: message = "⚠️ Missing DASEi websites:

" for code in missing_codes: message += f"• {code}: {DASEI_NAMES.get(code, 'Unknown')}
" message += "

To create them, click 'Create Missing DASEi Websites' action."
raise UserError(message)

# Create missing DASEi websites without importing hooks DASEI_CONFIGS = { 'dasei0': {'name': 'DASEi Quick Entry', 'sequence': 100}, 'dasei1': {'name': 'DASEi Einstiege', 'sequence': 101}, 'dasei2': {'name': 'DASEi Grundstufe', 'sequence': 102}, 'dasei3': {'name': 'DASEi Aufbaustufe', 'sequence': 103}, }
Website = env['website'] Company = env['res.company']
# Find DASEi company dasei_company = Company.search([ '|', '|', ('name', 'ilike', 'das ei'), ('name', 'ilike', 'dasei'), ('name', 'ilike', 'DAS Ei') ], limit=1)
if not dasei_company: raise UserError("No DASEi company found. Please create a company with 'DAS Ei' in the name first.")
existing_codes = set(Website.search([]).mapped('domain_code')) created = []
for code, config in DASEI_CONFIGS.items(): if code not in existing_codes: ws = Website.create({ 'name': config['name'], 'domain_code': code, 'company_id': dasei_company.id, 'sequence': config.get('sequence', 10), 'use_template_codes': True, 'use_milestones': True, }) created.append(ws)
if created: message = f"✅ Created {len(created)} DASEi website(s):\n\n" for ws in created: message += f"• {ws.domain_code}: {ws.name}\n" else: message = "✅ All DASEi websites already exist. Nothing to create."
raise UserError(message)
